insert into products
  (slug, name, name_en, price, age, age_en, short, short_en, long_desc, long_desc_en, care, care_en, tags, image_url, published)
values
('la-ferme-des-copains','La ferme des copains','Farmyard friends',30.0,'6 mois - 3 ans','6 months - 3 years','Un livre en feutrine tout doux à déchirer, pour découvrir les animaux de la ferme du bout des doigts.','A soft tearable felt book for discovering farm animals with little fingers.','« La ferme des copains » est un livre 100% feutrine, pensé pour les petites mains curieuses. Chaque page peut être délicatement déchirée puis rattachée grâce à une bande auto-agrippante, pour un jeu sans fin qui muscle la motricité fine. Bébé y découvre la vache, le mouton, le cochon et la poule à travers des formes simples et des couleurs douces, dans des tons Morandi apaisants qui n''agressent pas le regard. Sans danger, sans bruit de papier, ce livre accompagne les tout premiers instants de lecture et devient vite un doudou-livre que l''on retrouve partout.','“Farmyard friends” is a 100% felt book designed for curious little hands. Each page can be gently torn off and reattached with a hook-and-loop strip, for endless play that builds fine motor skills. Baby discovers the cow, the sheep, the pig and the hen through simple shapes and gentle Morandi tones that are easy on the eyes. Safe, silent (no paper rustling), this book accompanies the very first moments of reading and quickly becomes a comfort book carried everywhere.','Lavable en machine à 30°C, cycle délicat. Ne pas mettre au sèche-linge.','Machine washable at 30°C, delicate cycle. Do not tumble dry.','{"animaux","premiers mois","best-seller"}','https://www.monpremierlivre.com/assets/products/la-ferme-des-copains.png',true),
('sous-la-mer','Sous la mer','Under the sea',30.0,'1 - 4 ans','1 - 4 years','Un voyage sensoriel parmi les poissons, les vagues et les coquillages en feutrine texturée.','A sensory journey among fish, waves and shells in textured felt.','« Sous la mer » invite les tout-petits à explorer un monde aquatique tout en douceur : des vagues à froisser, un poisson à déchirer et recoller, une étoile de mer à caresser. Les textures variées stimulent le toucher et la curiosité, pendant que les couleurs bleu poudré et sable évoquent le calme de l''océan. Un livre pensé pour être manipulé sans crainte, encore et encore.','“Under the sea” invites little ones to gently explore an underwater world: waves to crinkle, a fish to tear off and reattach, a starfish to stroke. The varied textures stimulate touch and curiosity, while the powder-blue and sand tones evoke the calm of the ocean. A book designed to be handled fearlessly, again and again.','Lavable en machine à 30°C, cycle délicat. Séchage à plat recommandé.','Machine washable at 30°C, delicate cycle. Flat drying recommended.','{"ocean","sensoriel"}','https://www.monpremierlivre.com/assets/products/sous-la-mer.png',true),
('mes-premieres-couleurs','Mes premières couleurs','My first colours',30.0,'6 mois - 2 ans','6 months - 2 years','Un imagier tout en feutrine pour apprivoiser les couleurs en douceur, une page à la fois.','A felt picture book for gently learning colours, one page at a time.','Chaque page de cet imagier présente une couleur associée à un objet du quotidien (une pomme rouge, un ciel bleu, une feuille verte). Les pages détachables encouragent la préhension et le jeu libre, pendant qu''un adulte peut nommer les couleurs à voix haute. Un premier vocabulaire qui se construit par le jeu et le toucher, loin des écrans.','Each page of this picture book shows a colour linked to an everyday object (a red apple, a blue sky, a green leaf). The detachable pages encourage grasping and free play, while an adult can name the colours out loud. A first vocabulary built through play and touch, far from screens.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"couleurs","premiers mois","best-seller"}','https://www.monpremierlivre.com/assets/products/mes-premieres-couleurs.png',true),
('le-potager-de-mnamie','Le potager de mamie','Grandma''s vegetable patch',30.0,'1 - 4 ans','1 - 4 years','Des légumes en feutrine à récolter et déchirer, pour découvrir la nature du bout des doigts.','Felt vegetables to harvest and tear off, for discovering nature with little fingers.','Carotte, tomate, courgette : ce livre transforme le potager en terrain de jeu tactile. Les pages, à déchirer et refixer, imitent le geste de la récolte et donnent du sens au vocabulaire du jardin. Un bel outil pour parler d''alimentation et de nature dès le plus jeune âge, dans des teintes chaleureuses et naturelles.','Carrot, tomato, courgette: this book turns the vegetable patch into a tactile playground. The pages, made to be torn off and reattached, mimic the gesture of harvesting and give meaning to garden vocabulary. A lovely tool for talking about food and nature from the earliest age, in warm, natural tones.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"nature","vocabulaire"}',NULL,true),
('mon-corps-et-moi','Mon corps et moi','My body and me',30.0,'1 - 3 ans','1 - 3 years','Un livre en feutrine pour nommer les parties du corps et développer la conscience de soi.','A felt book for naming body parts and building self-awareness.','À travers des silhouettes douces et des pages à manipuler, l''enfant apprend à nommer sa tête, ses mains, ses pieds. Un support idéal pour accompagner l''autonomie et la confiance en soi dès les premiers mois, en complément des comptines et jeux du quotidien.','Through soft silhouettes and pages to handle, the child learns to name their head, hands and feet. An ideal tool for supporting independence and self-confidence from the earliest months, alongside everyday songs and games.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"corps","vocabulaire"}',NULL,true),
('petites-emotions','Petites émotions','Little feelings',30.0,'2 - 5 ans','2 - 5 years','Un livre en feutrine pour mettre des mots doux sur les grandes émotions des tout-petits.','A felt book for putting gentle words on little ones'' big feelings.','Joie, colère, tristesse, surprise : chaque page illustre une émotion avec des expressions simples et des textures à explorer. Un support précieux pour les parents qui souhaitent ouvrir le dialogue émotionnel dès le plus jeune âge, dans la douceur et sans jugement.','Joy, anger, sadness, surprise: each page illustrates an emotion with simple expressions and textures to explore. A precious tool for parents who want to open emotional dialogue from an early age, with gentleness and without judgement.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"émotions","nouveauté"}','https://www.monpremierlivre.com/assets/products/petites-emotions.png',true),
('la-meteo-du-jour','La météo du jour','Today''s weather',30.0,'2 - 5 ans','2 - 5 years','Soleil, pluie, nuages et vent à toucher, pour parler du temps qu''il fait chaque matin.','Sun, rain, clouds and wind to touch, for talking about the weather every morning.','Ce livre en feutrine accompagne le rituel matinal : quel temps fait-il aujourd''hui ? Les éléments à déchirer et replacer permettent de créer une routine ludique, idéale pour les crèches, les assistantes maternelles et la maison.','This felt book supports the morning ritual: what''s the weather like today? The pieces, made to be torn off and put back, create a playful routine, ideal for nurseries, childminders and home.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"routine","nouveauté"}',NULL,true),
('abc-en-feutrine','ABC en feutrine','Felt ABC',30.0,'3 - 6 ans','3 - 6 years','Un premier abécédaire tout doux pour apprivoiser les lettres avant l''entrée à l''école.','A gentle first alphabet book for getting to know letters before starting school.','Chaque lettre est associée à une texture et un petit mot illustré en feutrine, pour une première approche ludique et sensorielle de l''alphabet. Un bel objet transitionnel entre le livre-jeu de la petite enfance et les premiers apprentissages de la lecture.','Each letter is paired with a texture and a small illustrated felt word, for a first playful and sensory approach to the alphabet. A lovely transitional object between the play-books of early childhood and the first steps of learning to read.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"alphabet","best-seller"}','https://www.monpremierlivre.com/assets/products/abc-en-feutrine.png',true),
('au-dodo-petit-lapin','Au dodo, petit lapin','Off to sleep, little rabbit',30.0,'6 mois - 3 ans','6 months - 3 years','Un livre-doudou en feutrine pour accompagner le rituel du coucher en toute douceur.','A cuddly felt book for gently accompanying the bedtime ritual.','Une histoire toute simple pour préparer le sommeil : le petit lapin ferme les volets, enfile son pyjama, retrouve son doudou. Les pages en feutrine, agréables au toucher, apaisent et rassurent au moment du coucher, sans écran ni lumière stimulante.','A very simple story to prepare for sleep: the little rabbit closes the shutters, puts on pyjamas, finds their comfort toy. The felt pages, pleasant to touch, soothe and reassure at bedtime, with no screen or stimulating light.','Lavable en machine à 30°C, cycle délicat.','Machine washable at 30°C, delicate cycle.','{"coucher","doudou"}','https://www.monpremierlivre.com/assets/products/au-dodo-petit-lapin.png',true)
