on conflict (slug) do update set
  name = excluded.name, name_en = excluded.name_en, price = excluded.price,
  age = excluded.age, age_en = excluded.age_en, short = excluded.short, short_en = excluded.short_en,
  long_desc = excluded.long_desc, long_desc_en = excluded.long_desc_en,
  care = excluded.care, care_en = excluded.care_en, tags = excluded.tags,
  image_url = excluded.image_url, published = excluded.published;
